$(document).ready(function(){$('div[data-raty-input="on"]').each(function(){var a=$(this).data("source");$(this).raty({half:!0,path:$(this).data("path"),starOn:$(this).data("star-on"),starOff:$(this).data("star-off"),starHalf:$(this).data("star-half"),score:$(a).val(),scoreName:$(this).data("target")})}),$('div[data-raty="on"]').each(function(){$(this).raty({half:!0,path:$(this).data("path"),starOn:$(this).data("star-on"),starOff:$(this).data("star-off"),starHalf:$(this).data("star-half"),readOnly:!0,score:$(this).data("rating")})})});